UPDATE pages SET body = REPLACE(body, '<p>Puedes ver a quién has ghosteado y deshacerlo cuando quieras desde tu perfil.</p>', '<p>Puedes ver a quién has silenciado y deshacerlo cuando quieras desde tu perfil.</p>
<p>No lo confundas con el Ghost de los primeros {gm} minutos: ese velo es para todos, lo pone {site} y se levanta solo. Silenciar es una decisión tuya, entre dos personas, y dura hasta que la deshagas.</p>') WHERE slug = 'que-es';
