UPDATE pages SET body = REPLACE(body, '<h2>Aura</h2>', '<h2>Featured items</h2>
<p>There is one thing the cycle does not decide: <b>featured</b> items. Each front page may have one item pinned at the top, with a halo; it earns no δ, takes nobody''s turn and the rest keeps its order. It is placed by the administrator (while {site} finds its rhythm, to open conversation) or by any user using their aura: {pincost} on the front pages for {pinmin} minutes, {pincostorig} in Originals for {pinhorig} hours. If a user has one up, the administrator''s waits. It is always visible for what it is: a human choice, declared, outside the formula.</p>

<h2>Aura</h2>') WHERE slug = 'algoritmo.en';
